 string AnimationName(string k,string id){foreach(var p in Animations(k))if(string.Equals((string)p["id"],id,StringComparison.OrdinalIgnoreCase))return(string)p["name"]??id;return id=="default"?"Default":id;}
 string ReadUi(string key){if(key.StartsWith(AnimationUiPrefix,StringComparison.Ordinal)){var p=key.Substring(AnimationUiPrefix.Length).Split('.');if(p.Length>=4){var config=p[0]=="player"?PlayerKey:p[0]=="panel"?PanelKey:ClapperKey;var profile=p[2];if(p[3]=="name")return ProfileName(config,profile);if(p[3]=="startSequence"||p[3]=="endSequence"){var x=FindProfile(Read(config)["animationProfiles"] as JArray,profile);return(x?[p[3]] as JArray??new JArray()).ToString(Newtonsoft.Json.Formatting.None);}}return"";}if(!key.StartsWith(UiPrefix,StringComparison.Ordinal))return CPH.GetGlobalVar<string>(key,true);var q=key.Substring(UiPrefix.Length).Split('.');try{if(q[0]=="positions")return PositionSet(q[1]).ToString(Newtonsoft.Json.Formatting.None);if(q[0]=="branding"||q[0]=="visual"||q[0]=="title")return Find(q[0],q[1])?[q[2]]?.ToString()??"";if(q[0]=="entry")return EntryValue(q[1],q[2],q[3]);if(q[0]=="clapper")return q[1]=="animation"?AnimationName(ClapperKey,(string)Read(ClapperKey)["entryPoint"]?["animationProfile"]??"default"):Name("branding",(string)Read(ClapperKey)["entryPoint"]?["brandingPreset"]??"default");}catch{}return"";}
