 void SaveUi(string key,object value,bool persisted){if(!key.StartsWith(UiPrefix,StringComparison.Ordinal)&&!key.StartsWith(AnimationUiPrefix,StringComparison.Ordinal)){CPH.SetGlobalVar(key,value,persisted);return;}var v=value?.ToString()??"";try{if(key.StartsWith(AnimationUiPrefix,StringComparison.Ordinal)){var p=key.Substring(AnimationUiPrefix.Length).Split('.');var config=p[0]=="player"?PlayerKey:p[0]=="panel"?PanelKey:ClapperKey;if(p.Length>=4){if(p[3]=="name")SaveAnimationName(config,p[2],v);else if(p[3]=="startSequence"||p[3]=="endSequence")SaveSequence(config,p[2],p[3],v);}return;}var p2=key.Substring(UiPrefix.Length).Split('.');if(p2[0]=="positions"){SavePositions(p2[1],key,v);return;}if(p2[0]=="branding"||p2[0]=="visual"||p2[0]=="title")SavePreset(p2[0],p2[1],p2[2],v);else if(p2[0]=="entry")SaveEntry(p2[1],p2[2],p2[3],v);else if(p2[0]=="clapper")SaveClapper(p2[1],v);}catch(Exception ex){CPH.LogWarn("RTS Action Replay preset settings save failed: "+ex.Message);}}
